mapper.select:
select a.* from (SELECT ROW_NUMBER() OVER (order by reg_dt) AS row, oli.* FROM om_lgn_info oli where show_yn = 1
and lgn_id like concat('%',#{searchKeyword},'%') and lgn_nm like concat('%',#{searchKeyword},'%') and rgtr_id like concat('%',#{searchKeyword},'%')
order by row desc)a LIMIT 10 OFFSET #{offset}

mapper.update:
update om_lgn_info set 

	lgn_pswd = #{lgn_pswd}, 

lgn_type = #{lgn_type}, cmp_nm = #{cmp_nm}, uptr_id = #{uptr_id}, updt_dt = now() where lgn_id = #{lgn_id}

update om_lgn_info oli 
set visit_dt = now()
where lgn_id = #{lgn_id}
